custom_css:
/* ==========================================================
   MoodTube theme: Blurple  (theme format v2)
   A chat-app profile card: blurple banner, the track cover as a round
   avatar with a status dot (online while playing, idle on pause,
   offline when stopped) and a speaking ring, an activity card
   "Listening to MoodTube" with the progress bar, and a voice-panel
   style button bar. Dark greys + blurple, rounded sans.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Noto+Sans:wght@400;500;600;700;800&display=swap');

@keyframes bp-speak { 0%, 100% { border-color: #23a55a; } 50% { border-color: rgba(35, 165, 90, 0.45); } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --bp-blurple: #5865f2;
    --bp-blurple-hover: #4752c4;
    --bp-card: #232428;
    --bp-deep: #111214;
    --bp-bar: #1e1f22;
    --bp-hover: #35373c;
    --bp-selected: #404249;
    --bp-text: #dbdee1;
    --bp-strong: #f2f3f5;
    --bp-muted: #949ba4;
    --bp-icon: #b5bac1;
    --bp-green: #23a55a;
    --bp-yellow: #f0b232;
    --bp-red: #f23f43;
    --bp-offline: #80848e;
    --mt-text: var(--bp-text);
    --mt-text-dim: var(--bp-muted);
    --mt-text-on-accent: #ffffff;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: #4e5058;
    --mt-slider-track-height: 4px;
    --mt-slider-track-radius: 2px;
    --mt-slider-thumb-size: 10px;
    --mt-slider-thumb-bg: #ffffff;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--bp-text);
}
.mt-volume {
    --mt-slider-track: #4e5058;
    --mt-slider-track-height: 6px;
    --mt-slider-track-radius: 3px;
    --mt-slider-thumb-size: 12px;
    --mt-slider-thumb-bg: #ffffff;
    --mt-slider-thumb-bg-hover: #ffffff;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--bp-blurple);
}

/* ---------- Window: profile card with a banner ---------- */
.mt-player {
    container-type: size;
    padding: 36px 14px 12px;
    background: var(--bp-card);
    border: none;
    border-radius: 8px;
    color: var(--bp-text);
    font-family: 'Noto Sans', 'Segoe UI', Arial, sans-serif;
    box-shadow: none;
    backdrop-filter: none; -webkit-backdrop-filter: none;
    /* avatar grows with the window height, the banner follows it */
    --bp-av: clamp(70px, min(calc(100cqh - 190px), 62cqw), 180px);
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }
.mt-player::before {
    content: ''; position: absolute; left: 0; top: 0; width: 100%; height: calc(32px + var(--bp-av) / 2); z-index: 0; pointer-events: none;
    background: var(--bp-blurple); border-radius: 8px 8px 0 0;
}

/* ---------- Header: channel name on the banner ---------- */
.mt-player-header { top: 11px; left: 14px; right: 92px; align-items: center; gap: 6px; }
.mt-player-header-title { color: #ffffff; font-size: 13px; font-weight: 700; }
.mt-player-header-title::before { content: '# '; color: rgba(255, 255, 255, 0.6); font-weight: 600; }
.mt-player-status { color: rgba(255, 255, 255, 0.8); opacity: 1; font-size: 11px; font-weight: 500; }
.mt-window-btn {
    top: 8px; width: 22px; height: 22px; box-sizing: border-box; border-radius: 4px;
    display: flex; align-items: center; justify-content: center;
    font-size: 12px; color: rgba(255, 255, 255, 0.85); background: transparent;
}
.mt-window-btn:hover { color: #ffffff; background: rgba(0, 0, 0, 0.18); }
.mt-btn-search { right: 62px; }
.mt-btn-settings { right: 36px; }
.mt-btn-close { right: 10px; }
.mt-btn-search.mt-is-open { color: #ffffff !important; background: rgba(0, 0, 0, 0.22); }
.mt-resize-handle i { color: var(--bp-muted); }

/* ---------- Body ---------- */
.mt-player .mt-player-body { justify-content: flex-start; align-items: stretch; gap: 8px; }

/* avatar: the track cover, round, cut out of the banner */
.mt-cover {
    align-self: flex-start; margin-top: -4px; margin-left: 2px;
    width: var(--bp-av); height: var(--bp-av); box-sizing: border-box;
    border: 6px solid var(--bp-card); border-radius: 50%; background: var(--bp-card); box-shadow: none; overflow: visible;
}
.mt-cover-img { background: var(--bp-blurple); }
/* speaking ring while music plays */
.mt-cover-hole {
    z-index: 3; width: 100%; height: 100%; box-sizing: border-box; background: transparent;
    border: 3px solid transparent; border-radius: 50%; pointer-events: none;
}
.mt-player.mt-is-playing .mt-cover-hole { border-color: var(--bp-green); animation: bp-speak 1.6s ease-in-out infinite; }
/* status dot */
.mt-cover::after {
    content: ''; position: absolute; right: -4px; bottom: -4px; z-index: 4;
    width: 16px; height: 16px; box-sizing: content-box; border-radius: 50%;
    border: 5px solid var(--bp-card); background: var(--bp-offline);
}
.mt-player.mt-is-playing .mt-cover::after { background: var(--bp-green); }
.mt-player.mt-is-paused .mt-cover::after {
    background: radial-gradient(circle at 30% 30%, var(--bp-card) 0 4.5px, transparent 5px), var(--bp-yellow);
}

/* activity card: heading, track, progress */
.mt-track-info {
    align-items: flex-start; text-align: left; padding: 10px 34px 4px 12px;
    background: var(--bp-deep); border-radius: 8px 8px 0 0;
}
.mt-track-info::before {
    content: 'Listening to MoodTube'; display: block; margin-bottom: 6px;
    color: var(--bp-text); font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.02em;
}
.mt-track-title { color: var(--bp-strong); font-size: 15px; font-weight: 700; margin-bottom: 1px; }
.mt-track-subtitle { color: var(--bp-icon); font-size: 12px; font-weight: 500; }
.mt-btn-favorite { right: 10px; top: 8px; color: var(--bp-icon); font-size: 14px; }
.mt-btn-favorite:hover { color: var(--bp-text); }
.mt-btn-favorite.mt-is-active { color: var(--bp-red); }

.mt-progress {
    margin-top: -8px; padding: 4px 12px 10px; box-sizing: border-box;
    background: var(--bp-deep); border-radius: 0 0 8px 8px;
}
.mt-time { color: var(--bp-muted); font-size: 11px; font-weight: 500; }
.mt-player.moodtube-no-vol .mt-track-info { border-radius: 8px; padding-bottom: 10px; }

/* voice panel button bar */
.mt-controls {
    justify-content: space-between; gap: 2px; padding: 4px; box-sizing: border-box;
    background: var(--bp-bar); border-radius: 8px;
}
.mt-controls > .mt-btn {
    flex: 1 1 0; height: 32px; box-sizing: border-box; border-radius: 4px;
    display: flex; align-items: center; justify-content: center;
    font-size: 15px; color: var(--bp-icon); background: transparent;
}
.mt-controls > .mt-btn:hover { transform: none; color: var(--bp-text); background: var(--bp-hover); }
.mt-controls > .mt-btn-play { flex: 1.6 1 0; width: auto; font-size: 14px; color: #ffffff; background: var(--bp-blurple); }
.mt-controls > .mt-btn-play:hover { color: #ffffff; background: var(--bp-blurple-hover); }
.mt-btn-ai.mt-is-busy { color: var(--bp-green); }
.mt-volume { padding: 0 4px; box-sizing: border-box; }
.mt-volume-icon { color: var(--bp-icon); font-size: 12px; }

/* ---------- Wide bar ---------- */
.mt-player.moodtube-row-layout { padding-top: 34px; }
.mt-player.moodtube-row-layout::before { height: 30px; }
.mt-player.moodtube-row-layout .mt-player-body { align-items: center; gap: 10px; }
.mt-player.moodtube-row-layout .mt-cover { align-self: center; margin: 0; width: 46px; height: 46px; border-width: 0; }
.mt-player.moodtube-row-layout .mt-cover::after { width: 10px; height: 10px; border-width: 3px; right: -3px; bottom: -3px; }
.mt-player.moodtube-row-layout.mt-is-paused .mt-cover::after { background: var(--bp-yellow); }
.mt-player.moodtube-row-layout .mt-track-info { flex: 1 1 100px; min-width: 60px; padding: 0 22px 0 0; background: none; border-radius: 0; }
.mt-player.moodtube-row-layout .mt-track-info::before { display: none; }
.mt-player.moodtube-row-layout .mt-btn-favorite { right: 0; top: 0; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 13px; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 100px; min-width: 80px; margin: 0; padding: 0; background: none; border-radius: 0; }
.mt-player.moodtube-row-layout .mt-time-total { display: none; }
.mt-player.moodtube-row-layout .mt-controls { flex: 0 0 auto; width: 190px; padding: 3px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { height: 28px; font-size: 13px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 80px; min-width: 50px; }
.mt-player.moodtube-row-layout .mt-volume-high { display: none; }

/* ---------- Queue / playlists: member list ---------- */
.mt-panel { background: #2b2d31; padding-top: 42px; border-radius: inherit; }
.mt-panel-title { color: var(--bp-muted); font-size: 11px; font-weight: 700; letter-spacing: 0.02em; text-transform: uppercase; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--bp-icon); }
.mt-panel-close:hover, .mt-panel .mt-btn-accent:hover { color: var(--bp-text); }
.mt-queue-item { background: transparent; border-color: transparent; border-radius: 4px; }
.mt-queue-item:hover { background: var(--bp-hover); }
.mt-queue-item.mt-is-current { background: var(--bp-selected); border-color: transparent; }
.mt-queue-thumb { border-radius: 50%; }
.mt-queue-thumb.mt-is-empty { background: var(--bp-blurple); }
.mt-queue-title { color: var(--bp-muted); font-size: 13px; font-weight: 500; }
.mt-queue-item:hover .mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--bp-strong); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: var(--bp-red); }
.mt-queue-now { color: var(--bp-green); }
.mt-queue-add { color: var(--bp-icon); }
.mt-queue-dislike { background-color: var(--bp-icon); }
.mt-queue-empty { color: var(--bp-muted); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked { background: var(--bp-blurple); border-color: var(--bp-blurple); box-shadow: none; color: #ffffff; }

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: #1a1b1e transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 8px; height: 8px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: #2b2d31; border-radius: 4px; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: #1a1b1e; border-radius: 4px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(0, 0, 0, 0.7);
    --mt-modal-shadow: none;
    --mt-text-strong: var(--bp-strong);
    --mt-divider: rgba(255, 255, 255, 0.06);
}
#mt-settings-modal .mt-flex-container { border: none; border-radius: 8px; }
#mt-settings-modal .mt-header h3 { font-weight: 700; }
#mt-settings-modal .mt-close { color: var(--bp-icon); }
#mt-settings-modal .mt-tag { background-color: #2b2d31; border-color: transparent; border-radius: 4px; box-shadow: none; color: var(--bp-text); }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: var(--bp-hover); border-color: transparent;
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--bp-blurple); border-color: var(--bp-blurple); color: #ffffff; box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: #4e5058; border-color: transparent; border-radius: 4px; color: #ffffff; }
#mt-settings-modal .mt-btn-test:hover { background: #6d6f78; }
#mt-settings-modal .mt-subpanel { background: #2b2d31; border-radius: 8px; }

/* ---------- Search panel and playlists ---------- */
.mt-panel-search { --mt-bg-primary: #2b2d31; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #ffffff) !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--bp-blurple); --mt-pl-spotify-tab-text: #ffffff; }
.mt-pl-tabs { background: var(--bp-bar); border: none; border-radius: 6px; }
.mt-pl-tool { background: #4e5058; border-color: transparent; border-radius: 4px; color: #ffffff; }
.mt-pl-tool:hover { background: #6d6f78; }
.mt-pl-tool.mt-pl-play { background: var(--bp-green); border-color: var(--bp-green); color: #ffffff; }
.mt-pl-inline-cancel { background: #4e5058; color: #ffffff; }
.mt-pl-cover-empty { background: var(--bp-blurple); color: #ffffff; }
.mt-pl-modal { --mt-overlay: rgba(0, 0, 0, 0.7); }
.mt-pl-modal-box { background: #313338; border: none; border-radius: 8px; }
.mt-pl-modal-track { border-bottom-color: rgba(255, 255, 255, 0.06); }
.mt-pl-option { background: #2b2d31; border-radius: 4px; }
.mt-pl-option:hover { background: var(--bp-hover); }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--bp-green); }

@container (max-width: 300px) { .mt-player .mt-player-status { display: none; } }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Noto Sans', 'Segoe UI', Arial, sans-serif;
  --mt-dock-cover-radius: 50%;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 50%;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: 88px; }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 28px; height: 28px; min-width: 28px; padding: 0; box-sizing: border-box; display: flex; align-items: center; justify-content: center; line-height: 1; top: 5px; font-size: 14px; }
#moodtube-mini-player .mt-window-btn.mt-btn-close { right: 7px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-settings { right: 39px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: 71px; left: auto; }
#moodtube-mini-player .mt-window-btn.mt-btn-lyrics { right: 103px; left: auto; }
/* == /window buttons == */
